import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第三册：培养技能 · Lesson 40 Who's who","description":"学习 反身代词与相互代词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 40 Who's who","description":"学习 反身代词与相互代词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 反身代词与相互代词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 39 Nothing to worry about","link":"/life/english/new-concept/book-3/unit-02/lesson-039"},"next":{"text":"第三册：培养技能 · Lesson 41 Illusions of pastoral peace","link":"/life/english/new-concept/book-3/unit-03/lesson-041"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 39 Nothing to worry about","link":"/life/english/new-concept/book-3/unit-02/lesson-039"},"next":{"text":"第三册：培养技能 · Lesson 41 Illusions of pastoral peace","link":"/life/english/new-concept/book-3/unit-03/lesson-041"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-040.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-040.md"}`),i={name:"life/english/new-concept/book-3/unit-02/lesson-040.md"};function s(l,e,r,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-40-who-s-who" tabindex="-1">第三册：培养技能 · Lesson 40 Who&#39;s who <a class="header-anchor" href="#第三册-培养技能-·-lesson-40-who-s-who" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 40 Who&#39;s who&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕身份混淆、角色扮演和真假判断，练习清楚追踪说话人与动作执行者。学习反身代词强调本人或回指同一主体，并区分 each other 的相互关系。故事中出现多人时，代词选择必须服务于理解，必要时重复名字而不要过度省略。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>identity</td><td>/aɪˈdentəti/</td><td>n.</td><td>身份</td><td>confirm an identity</td></tr><tr><td>impersonate</td><td>/ɪmˈpɜːsəneɪt/</td><td>v.</td><td>冒充</td><td>impersonate an official</td></tr><tr><td>confusion</td><td>/kənˈfjuːʒən/</td><td>n.</td><td>混淆</td><td>avoid confusion</td></tr><tr><td>introduce</td><td>/ˌɪntrəˈdjuːs/</td><td>v.</td><td>介绍</td><td>introduce a guest</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in person — 亲自到场</li><li>mistake A for B — 把A误认为B</li></ul><h2 id="语法讲解-反身代词与相互代词" tabindex="-1">语法讲解：反身代词与相互代词 <a class="header-anchor" href="#语法讲解-反身代词与相互代词" aria-label="Permalink to &quot;语法讲解：反身代词与相互代词&quot;">​</a></h2><p>myself、yourself、himself 等反身代词可在主语与宾语指同一对象时使用，也可放在名词或句末强调本人。by oneself 常表示独自或不借助他人。each other 表示不同成员之间的相互动作，与 themselves 意义不同。They introduced themselves 是各自介绍自己，They introduced each other 是互相介绍对方。反身代词不能只为显得正式而代替普通宾格，例如 Please contact me 通常比 contact myself 更合适，除非有明确反身或强调语境。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The two actors introduced themselves before they introduced each other to the director.</p></blockquote><p>两位演员先介绍自己，然后向导演介绍了对方。</p><p>themselves 回指各自，each other 表示相互对象；两个短语改变动作方向。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>They looked at themselves 表示看自己，looked at each other 表示彼此对视，不能互换。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 themselves 与 each other 时加重区分；画两个人物箭头，听自己的句子并判断箭头指回自己还是指向对方。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Nina introduced herself as the host. She then introduced Omar to the audience. Omar had prepared the entire demonstration by himself.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句说明一次角色排练，明确谁介绍谁以及谁独自准备。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>人名和代词交替使用但指向清楚，by himself 补充独立准备的信息。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句的 themselves 指谁？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两位演员各自本人。</p><p><strong>解析：</strong> 反身代词回指主语成员。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>将“她独自完成了布景”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She finished the set by herself.</p><p><strong>解析：</strong> by herself 表示独立完成。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改正普通联系方式：Please email myself.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Please email me.</p><p><strong>解析：</strong> 没有反身或强调条件时使用宾格 me。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：反身代词与相互代词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-039">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-041">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
